import com.comsol.model.*;import com.comsol.model.util.*;import java.io.*;import java.util.*;
public class LocalReviewModel20261017{
 static String outward(String v){return "if(up(dom)>0,-uflux_spatial("+v+"),-dflux_spatial("+v+"))";}
 public static void main(String[] a){try{ModelUtil.initStandalone(false);ModelUtil.showPlots(false);ModelUtil.showProgress(false);Model m=ModelUtil.load("BinaryReview",a[0]);String hash=LFFrozenRecovery.hash(m.sol("sol1").getU());String[] names={"mass","H2","H2O","O2","N2"};
  m.physics("tcs").label("INACTIVE four-species reference: w1/w2/w3/w4 are old fields; use bt_* for current model");m.physics("tbin").label("ACTIVE binary Maxwell-Stefan: bA=H2 fuel / O2 air; bB=H2O fuel / N2 air");m.study("std1").label("Physical binary steady state; current composition uses bt_* aliases");m.study("bfStudy").label("Frozen physical solution: conservative numerical flux recovery");m.result().dataset("bfData").label("Conservative numerical flux dataset; use bf_* variables");
  for(String tag:new String[]{"bfIface","bfPort"}){m.component("comp1").variable().create(tag);m.component("comp1").variable(tag).selection().geom("geom1",1);m.component("comp1").variable(tag).selection().set(tag.equals("bfIface")?new int[]{4,10}:new int[]{1,9,12,16});}
  for(String side:new String[]{"up","down"}){String suffix="_"+side,op=side.equals("up")?"uflux_spatial":"dflux_spatial",mass="-"+op+"(bfR)",active="-"+op+"(bfS)",fuel=side+"(dom)>=4";m.component("comp1").variable("bfIface").set("bf_mass"+suffix,mass);m.component("comp1").variable("bfIface").set("bf_active"+suffix,active);String[] ex={mass,"if("+fuel+",("+active+"),0[kg/(m^2*s)])","if("+fuel+",("+mass+")-("+active+"),0[kg/(m^2*s)])","if("+fuel+",0[kg/(m^2*s)],("+active+"))","if("+fuel+",0[kg/(m^2*s)],("+mass+")-("+active+"))"};for(int i=0;i<5;i++)m.component("comp1").variable("bfIface").set("bf_"+names[i]+suffix,ex[i],"Outward numerical flux from "+side+" side; absent components structurally zero");}
  String fm="withsol('sol1',fp.rho*(u*nx+v*ny))",fa="if(x<0.05[m],("+outward("bfS")+")+withsol('sol1',bA)*(("+fm+")-("+outward("bfR")+")),withsol('sol1',fp.rho*bA*(u*nx+v*ny)))",fuel="y>0.00131[m]";String[] ex={fm,"if("+fuel+",("+fa+"),0[kg/(m^2*s)])","if("+fuel+",("+fm+")-("+fa+"),0[kg/(m^2*s)])","if("+fuel+",0[kg/(m^2*s)],("+fa+"))","if("+fuel+",0[kg/(m^2*s)],("+fm+")-("+fa+"))"};for(int i=0;i<5;i++)m.component("comp1").variable("bfPort").set("bf_"+names[i]+"_port",ex[i]);
  for(int b:new int[]{4,10}){String tag="bfInterface"+b;m.result().create(tag,"PlotGroup1D");m.result(tag).label("Numerical mass flux: interface "+b);m.result(tag).set("data","bfData");for(int i=0;i<2;i++){String line="line"+i;m.result(tag).create(line,"LineGraph");m.result(tag).feature(line).selection().set(new int[]{b});m.result(tag).feature(line).set("expr",i==0?"bf_mass_up":"-bf_mass_down");m.result(tag).feature(line).set("xdata","expr");m.result(tag).feature(line).set("xdataexpr","x");}}
  m.result().create("binaryTemperature","PlotGroup2D");m.result("binaryTemperature").set("data","dset1");m.result("binaryTemperature").label("CURRENT binary temperature; composition aliases bt_H2, bt_H2O, bt_O2, bt_N2");m.result("binaryTemperature").create("surf1","Surface");m.result("binaryTemperature").feature("surf1").set("expr","T");
  m.sol(m.result().dataset("bfData").getString("solution")).updateSolution();m.result().numerical().create("bfNamedCheck","IntLine");m.result().numerical("bfNamedCheck").set("data","bfData");m.result().numerical("bfNamedCheck").set("intorder",8);PrintWriter p=new PrintWriter(a[2],"UTF-8");p.println("boundary,quantity,value");for(int b:new int[]{1,9,12,16})for(String name:names){m.result().numerical("bfNamedCheck").selection().set(new int[]{b});m.result().numerical("bfNamedCheck").set("expr",new String[]{"bf_"+name+"_port"});p.printf(Locale.US,"%d,%s,%.17g%n",b,name,m.result().numerical("bfNamedCheck").getReal()[0][0]);}p.close();if(!hash.equals(LFFrozenRecovery.hash(m.sol("sol1").getU())))throw new RuntimeException("Review annotation changed physical solution");LocalMeshQuality20261017.export(m,a[3]);m.label("Local refinement validation; current composition bt_*; editable flux/field plots");m.save(a[1]);System.out.println("BINARY_REVIEW_SAVED");System.exit(0);
 }catch(Throwable e){e.printStackTrace(System.out);System.exit(1);}}
}
